{
  "name": "grunt-uncss",
  "description": "A grunt task for generating CSS files containing only those styles used in your project.",
  "version": "0.10.1",
  "homepage": "https://github.com/uncss/grunt-uncss",
  "author": "Addy Osmani <addyosmani@gmail.com> (https://addyosmani.com/)",
  "maintainers": [
    "Addy Osmani <addyosmani@gmail.com> (https://addyosmani.com/)",
    "XhmikosR <xhmikosr@gmail.com> (https://github.com/XhmikosR)"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/uncss/grunt-uncss.git"
  },
  "bugs": {
    "url": "https://github.com/uncss/grunt-uncss/issues"
  },
  "license": "MIT",
  "keywords": [
    "gruntplugin",
    "uncss",
    "css"
  ],
  "files": [
    "tasks/*.js"
  ],
  "engines": {
    "node": ">=14.18.0"
  },
  "scripts": {
    "mocha": "mocha \"tests/*.js\"",
    "xo": "xo",
    "fix": "xo --fix",
    "test": "npm run xo && grunt test && npm run mocha"
  },
  "dependencies": {
    "chalk": "^4.1.2",
    "maxmin": "^3.0.0",
    "uncss": "^0.17.3"
  },
  "devDependencies": {
    "chai": "^4.3.6",
    "grunt": "^1.5.3",
    "mocha": "^10.2.0",
    "time-grunt": "^2.0.0",
    "xo": "^0.53.1"
  },
  "peerDependencies": {
    "grunt": ">=0.4.0"
  },
  "xo": {
    "space": 4,
    "ignores": [
      "tests/app/**"
    ],
    "rules": {
      "capitalized-comments": "off",
      "comma-dangle": "off",
      "object-curly-spacing": [
        "error",
        "always"
      ],
      "unicorn/filename-case": "off",
      "unicorn/prefer-module": "off",
      "unicorn/prevent-abbreviations": "off"
    }
  }
}

/* eslint-env mocha */

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { expect } = require('chai');
const uncss = require('uncss');

const readFile = file => fs.readFileSync(path.join(__dirname, file), 'utf8');

let rawcss = readFile('output.css');
const urlcss = readFile('outputUrl.css');
const tests = fs.readdirSync(path.join(__dirname, 'fixtures/'));

/* Only read through CSS files */
for (const test of tests) {
    if (test.includes('.css')) {
        readFile(`fixtures/${test}`);
    }
}

/*
Tests without grunt-uncss
*/
describe('uncss', () => {
    /* Wait until uncss finished doing its thing before running our tests */
    before(done => {
        /* New api from issue #44 */
        uncss(readFile('index.html'), {
            csspath: 'tests'
        }, (err, output) => {
            if (err) {
                throw err;
            }

            rawcss = output;
            done();
        });
    });

    it('should output something', () => {
        expect(rawcss).not.to.equal(false);
        expect(urlcss).not.to.equal(false);
    });

    it('should not be an empty string', () => {
        expect(rawcss).to.have.length.above(0);
    });

    it('should read .uncssrc files', done => {
        uncss(readFile('index.html'), {
            csspath: 'tests',
            report: true,
            uncssrc: path.normalize('tests/.uncssrc')
        }, (err, res, report) => {
            if (err) {
                return done(err);
            }

            expect(err).to.equal(null);
            expect(res).to.equal(rawcss);
            expect(report.original).not.to.equal(null);
            done();
        });
    });

    /* We're testing that the CSS is stripped out from the result,
       not that the result contains the CSS in the unused folder. */
    for (const test of tests) {
        it(`should handle ${test.split('.')[0]}`, () => {
            expect(rawcss).to.not.include.string(readFile(`unused/${test}`));
        });
    }
});

/* eslint-env browser */

(function () {
    'use strict';

    var container;
    var row;
    var column;
    var heading;
    var text;

    container = document.getElementById('add-here');

    if (!container) {
        return;
    }

    row = document.createElement('div');
    row.className = 'row';

    column = document.createElement('div');
    column.className = 'col-lg-4';

    heading = document.createElement('h3');
    heading.className = 'test-green';
    heading.innerHTML = 'PhantomJS';

    text = document.createTextNode('PhantomJS works! This paragraph was added at runtime.');

    column.appendChild(heading);
    column.appendChild(text);
    row.appendChild(column);

    if (container.firstChild) {
        container.insertBefore(row, container.firstChild);
    } else {
        container.appendChild(row);
    }
})();

