.green {
  color: green;
}

.blue ~ span {
  color: green;
}

div > span {
  color: #000;
}

#playground, #fairground {
  color: white;
}

div:not(#battleground) {
  display: inline-block;
}

span:nth-child(3) {
  border-bottom: 1px solid blue;
}

h2 {
  font-size: 1.5rem;
}

p {
  font-size: 1em;
}

#battleground + div {
  background: white;
}

span:nth-of-type(4) {
  border-bottom: 1px solid blue;
}

.red ~ span {
    color: blue;
}

.blue ~ span {
    color: green;
}

